using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Nibble-level bit-reverse lookup: index 0x0–0xF → reversed nibble
    private static ReadOnlySpan<byte> NibbleLut => [
        0x0, 0x8, 0x4, 0xC, 0x2, 0xA, 0x6, 0xE,
        0x1, 0x9, 0x5, 0xD, 0x3, 0xB, 0x7, 0xF
    ];

    public static void ReverseInPlace(Span<byte> data)
    {
        int i = 0;

        // --- 256-bit SIMD path (AVX2 or ARM SVE/NEON with 256-bit vectors) ---
        if (Vector256.IsHardwareAccelerated)
        {
            Vector256<byte> lowNibbleMask = Vector256.Create((byte)0x0F);
            Vector256<byte> lut = Vector256.Create(NibbleLut).WithUpper(Vector128.Create(NibbleLut));

            int limit = data.Length - Vector256<byte>.Count;
            ref byte ptr = ref MemoryMarshal.GetReference(data);

            for (; i <= limit; i += Vector256<byte>.Count)
            {
                Vector256<byte> vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);

                // Split into nibbles, look up each reversed nibble, recombine swapped
                Vector256<byte> lo = vec & lowNibbleMask;
                Vector256<byte> hi = Vector256.ShiftRightLogical(vec.AsInt32(), 4).AsByte() & lowNibbleMask;

                Vector256<byte> reversedLo = Vector256.Shuffle(lut, lo);
                Vector256<byte> reversedHi = Vector256.Shuffle(lut, hi);

                // Low nibble becomes high nibble and vice-versa
                Vector256<byte> result = Vector256.ShiftLeft(reversedLo.AsInt32(), 4).AsByte() | reversedHi;
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
        }
        // --- 128-bit SIMD path (SSE2/SSSE3, NEON, etc.) ---
        else if (Vector128.IsHardwareAccelerated)
        {
            Vector128<byte> lowNibbleMask = Vector128.Create((byte)0x0F);
            Vector128<byte> lut = Vector128.Create(NibbleLut);

            int limit = data.Length - Vector128<byte>.Count;
            ref byte ptr = ref MemoryMarshal.GetReference(data);

            for (; i <= limit; i += Vector128<byte>.Count)
            {
                Vector128<byte> vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);

                Vector128<byte> lo = vec & lowNibbleMask;
                Vector128<byte> hi = Vector128.ShiftRightLogical(vec.AsInt32(), 4).AsByte() & lowNibbleMask;

                Vector128<byte> reversedLo = Vector128.Shuffle(lut, lo);
                Vector128<byte> reversedHi = Vector128.Shuffle(lut, hi);

                Vector128<byte> result = Vector128.ShiftLeft(reversedLo.AsInt32(), 4).AsByte() | reversedHi;
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
        }

        // Scalar fallback for remaining bytes
        for (; i < data.Length; i++)
        {
            byte b = data[i];
            data[i] = (byte)((NibbleLut[b & 0x0F] << 4) | NibbleLut[b >> 4]);
        }
    }
}

